DELETE FROM AUD_ATTEMPT_ACKNOWLEDGEMENTS WHERE ATTEMPT_ID IN (
SELECT t.ATTEMPT_ID AS row_id FROM AUD_ATTEMPT_ACKNOWLEDGEMENTS t WHERE (EXISTS (SELECT 1 FROM AUD_PIPELINES_RUN_LOG r JOIN CFG_PIPELINES p ON p.PIPELINE_ID=r.PIPELINE_ID WHERE p.PROJECT_ID=:project_id AND r.STATUS IN ('SUCCESS','FAILED','SKIPPED','CANCELLED') AND r.END_DATE < :cutoff AND EXISTS (SELECT 1 FROM AUD_TASK_RUN_LOG tr WHERE tr.PIPELINE_RUN_ID=r.PIPELINE_RUN_ID AND EXISTS (SELECT 1 FROM AUD_TASK_ATTEMPTS a WHERE a.TASK_RUN_ID=tr.TASK_RUN_ID AND a.ATTEMPT_ID=t.ATTEMPT_ID))))
ORDER BY t.ATTEMPT_ID LIMIT 10000
)
